import { Controller, Post, Body, UseGuards, Get, Request, Query, Response } from '@nestjs/common';
import { ApiTags, ApiOperation, ApiBearerAuth } from '@nestjs/swagger';
import { Response as ExpressResponse } from 'express';
import { AuthService } from './auth.service';
import { CreateUserDto, LoginDto } from '../users/dto/user.dto';
import { AuthGuard } from '@nestjs/passport';
import { ForgotPasswordDto, ResetPasswordDto } from './dto/password-reset.dto';

@ApiTags('auth')
@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  private setRefreshCookie(res: ExpressResponse, refreshToken: string) {
    const isProduction = (process.env.NODE_ENV || '').toLowerCase() === 'production';
    res.cookie('refreshToken', refreshToken, {
      httpOnly: true,
      secure: isProduction,
      sameSite: isProduction ? 'none' : 'lax',
      maxAge: 7 * 24 * 60 * 60 * 1000,
      path: '/',
    });
  }

  private extractRefreshTokenFromCookie(req: any): string | null {
    const rawCookie = String(req?.headers?.cookie || '');
    if (!rawCookie) return null;
    const entries = rawCookie.split(';').map((part) => part.trim());
    const match = entries.find((entry) => entry.startsWith('refreshToken='));
    if (!match) return null;
    return decodeURIComponent(match.slice('refreshToken='.length));
  }

  @Post('register')
  @ApiOperation({ summary: 'User registration' })
  async register(
    @Body() createUserDto: CreateUserDto,
    @Response({ passthrough: true }) res: ExpressResponse
  ) {
    const authResult = await this.authService.register(createUserDto);
    this.setRefreshCookie(res, authResult.refreshToken);
    return authResult;
  }

  @Post('register-invited')
  @ApiOperation({ summary: 'Invited user registration with pending activation' })
  async registerInvited(@Body() createUserDto: CreateUserDto) {
    return this.authService.registerInvited(createUserDto);
  }

  @Post('login')
  @ApiOperation({ summary: 'User login' })
  async login(@Body() loginDto: LoginDto, @Response({ passthrough: true }) res: ExpressResponse) {
    const authResult = await this.authService.login(loginDto);
    this.setRefreshCookie(res, authResult.refreshToken);
    return authResult;
  }

  @Post('refresh')
  @ApiOperation({ summary: 'Refresh access token' })
  async refresh(
    @Request() req,
    @Body() body: { refreshToken?: string },
    @Response({ passthrough: true }) res: ExpressResponse
  ) {
    const fromBody = body?.refreshToken?.trim() || null;
    const fromCookie = this.extractRefreshTokenFromCookie(req);
    const token = fromBody || fromCookie;
    const authResult = await this.authService.refreshTokens(token || '');
    this.setRefreshCookie(res, authResult.refreshToken);
    return authResult;
  }

  @Post('forgot-password')
  @ApiOperation({ summary: 'Request a password reset link' })
  async forgotPassword(@Body() forgotPasswordDto: ForgotPasswordDto) {
    return this.authService.forgotPassword(forgotPasswordDto);
  }

  @Post('reset-password')
  @ApiOperation({ summary: 'Reset password using reset token' })
  async resetPassword(@Body() resetPasswordDto: ResetPasswordDto) {
    return this.authService.resetPassword(resetPasswordDto);
  }

  @Get('me')
  @UseGuards(AuthGuard('jwt'))
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Get current user profile' })
  async getMe(@Request() req) {
    return {
      id: req.user.id,
      email: req.user.email,
      username: req.user.username,
      fullName: req.user.fullName,
      role: req.user.role,
      avatar: req.user.avatar,
    };
  }

  @Get('debug/permissions')
  @ApiOperation({
    summary: 'Temporary debug endpoint for effective menu permissions by identifier',
  })
  async debugPermissions(@Query('identifier') identifier: string, @Query('key') key?: string) {
    return this.authService.debugPermissionsByIdentifier(identifier, key);
  }
}

import { Injectable, UnauthorizedException, BadRequestException, Logger } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcryptjs';
import { ConfigService } from '@nestjs/config';
import { UsersService } from '../users/users.service';
import { LoginDto } from '../users/dto/user.dto';
import { NotificationsService } from '../notifications/notifications.service';
import { ForgotPasswordDto, ResetPasswordDto } from './dto/password-reset.dto';

@Injectable()
export class AuthService {
  private readonly logger = new Logger(AuthService.name);

  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
    private readonly usersService: UsersService,
    private readonly notificationsService: NotificationsService
  ) {}

  async register(createUserDto: any) {
    const existingUser = await this.usersService.findByEmail(createUserDto.email);
    if (existingUser) {
      throw new BadRequestException('Email already registered');
    }

    const user = await this.usersService.create(null, createUserDto);
    return this.generateTokens(user);
  }

  async registerInvited(createUserDto: any) {
    const normalizedEmail = createUserDto.email?.trim().toLowerCase();
    const normalizedUsername = createUserDto.username?.trim().toLowerCase();

    const existingUser =
      (await this.usersService.findByEmail(normalizedEmail)) ||
      (await this.usersService.findByUsername(normalizedUsername));

    if (existingUser) {
      throw new BadRequestException('Email or username already registered');
    }

    const user = await this.usersService.create(null, {
      ...createUserDto,
      email: normalizedEmail,
      username: normalizedUsername,
      status: 'inactive',
    });

    return {
      message: 'Votre compte a ├®t├® cr├®├® et reste en attente dÔÇÖactivation par un administrateur.',
      user: {
        id: user.id,
        email: user.email,
        username: user.username,
        fullName: user.fullName,
        role: user.role,
        status: user.status,
      },
    };
  }

  async login(loginDto: LoginDto) {
    const identifier = loginDto.email?.trim().toLowerCase();
    const user =
      (await this.usersService.findByEmail(identifier)) ||
      (await this.usersService.findByUsername(identifier));
    if (!user) {
      throw new UnauthorizedException('Invalid credentials');
    }

    if (user.status !== 'active') {
      throw new UnauthorizedException('Your account is awaiting activation by an administrator');
    }

    const isPasswordValid = await this.usersService.validatePassword(user, loginDto.password);
    if (!isPasswordValid) {
      throw new UnauthorizedException('Invalid credentials');
    }

    return this.generateTokens(user);
  }

  async validateUser(id: string) {
    const user = await this.usersService.findOne(id);
    if (!user) {
      throw new UnauthorizedException('User not found');
    }
    return user;
  }

  private generateTokens(user: any) {
    const payload = {
      sub: user.id,
      id: user.id,
      email: user.email,
      role: user.role,
    };

    const accessToken = this.jwtService.sign(payload, {
      expiresIn: '15m',
    });

    const refreshToken = this.jwtService.sign(payload, {
      expiresIn: '7d',
    });

    return {
      accessToken,
      refreshToken,
      user: {
        id: user.id,
        email: user.email,
        username: user.username,
        fullName: user.fullName,
        role: user.role,
        avatar: user.avatar,
      },
    };
  }

  async refreshTokens(refreshToken: string) {
    try {
      const payload = this.jwtService.verify(refreshToken);
      const user = await this.validateUser(payload?.id || payload?.sub);
      return this.generateTokens(user);
    } catch (error) {
      throw new UnauthorizedException('Invalid refresh token');
    }
  }

  async forgotPassword(forgotPasswordDto: ForgotPasswordDto) {
    const normalizedEmail = forgotPasswordDto.email.trim().toLowerCase();
    const user = await this.usersService.findByEmailInsensitive(normalizedEmail);

    if (!user) {
      return {
        message: 'Si cette adresse email existe, un lien de reinitialisation a ete envoye.',
      };
    }

    const resetToken = this.jwtService.sign(
      {
        sub: user.id,
        email: user.email,
        type: 'password_reset',
      },
      {
        expiresIn: '30m',
      }
    );

    const frontendBaseUrl =
      this.configService.get<string>('FRONTEND_URL') ||
      process.env.FRONTEND_URL ||
      'http://localhost:5173';
    const resetUrl = `${frontendBaseUrl}/reset-password?token=${encodeURIComponent(resetToken)}`;

    await this.notificationsService.sendEmailNotification({
      to: user.email,
      subject: 'Reinitialisation de votre mot de passe',
      text: `Une demande de reinitialisation de mot de passe a ete recue.\n\nOuvrez ce lien pour definir un nouveau mot de passe : ${resetUrl}\n\nCe lien expire dans 30 minutes.`,
      html: `<p>Une demande de reinitialisation de mot de passe a ete recue.</p><p><a href="${resetUrl}">Definir un nouveau mot de passe</a></p><p>Ce lien expire dans 30 minutes.</p>`,
    });

    this.logger.log(`Password reset requested for email=${normalizedEmail}`);

    return {
      message: 'Si cette adresse email existe, un lien de reinitialisation a ete envoye.',
    };
  }

  async resetPassword(resetPasswordDto: ResetPasswordDto) {
    const { token, newPassword } = resetPasswordDto;

    let payload: any;
    try {
      payload = this.jwtService.verify(token);
    } catch {
      throw new BadRequestException('Le lien de reinitialisation est invalide ou expire.');
    }

    if (payload?.type !== 'password_reset' || !payload?.sub) {
      throw new BadRequestException('Le lien de reinitialisation est invalide.');
    }

    const user = await this.usersService.findEntityById(payload.sub);
    const isSamePassword = await this.usersService.validatePassword(user, newPassword);
    if (isSamePassword) {
      throw new BadRequestException("Le nouveau mot de passe doit etre different de l'ancien.");
    }

    await this.usersService.updatePassword(user.id, newPassword);

    return { message: 'Mot de passe reinitialise avec succes.' };
  }

  async debugPermissionsByIdentifier(identifier: string, key?: string) {
    const debugKey =
      this.configService.get<string>('PERMISSIONS_DEBUG_KEY') ||
      process.env.PERMISSIONS_DEBUG_KEY ||
      'debug-permissions-local';
    const isProduction = (process.env.NODE_ENV || '').toLowerCase() === 'production';
    const providedKey = (key || '').trim();

    if (isProduction && providedKey !== debugKey) {
      throw new UnauthorizedException('Invalid debug key');
    }

    if (!isProduction && providedKey && providedKey !== debugKey) {
      throw new UnauthorizedException('Invalid debug key');
    }

    return this.usersService.getMenuPermissionsByIdentifier(identifier);
  }
}

import { Injectable } from '@nestjs/common';
